import itertools
import json

def solve():
    # Define the puzzle parameters
    houses = [1, 2]
    categories = {
        "Name": ["Arnold", "Eric"],
        "Education": ["associate", "high school"],
        "Height": ["short", "very short"],
        "Lunch": ["grilled cheese", "pizza"],
        "Drink": ["tea", "water"],
    }

    # Prepare permutations for each category (mapping houses -> values by position)
    perms_by_cat = {cat: list(itertools.permutations(vals, len(houses))) for cat, vals in categories.items()}

    # Helper to get the house index (1-based) of a given value in a category
    def get_house(assign, category, value):
        return assign[category].index(value) + 1

    # Check all combinations of category assignments
    cats = list(categories.keys())
    for selection in itertools.product(*(perms_by_cat[cat] for cat in cats)):
        assignment = {cat: perm for cat, perm in zip(cats, selection)}

        # Apply clues:
        # 1. The person who is very short is the person who is a pizza lover.
        if get_house(assignment, "Height", "very short") != get_house(assignment, "Lunch", "pizza"):
            continue

        # 2. The person who loves eating grilled cheese is in the second house.
        if get_house(assignment, "Lunch", "grilled cheese") != 2:
            continue

        # 3. The person with a high school diploma is the person who is a pizza lover.
        if get_house(assignment, "Education", "high school") != get_house(assignment, "Lunch", "pizza"):
            continue

        # 4. The tea drinker is the person who loves eating grilled cheese.
        if get_house(assignment, "Drink", "tea") != get_house(assignment, "Lunch", "grilled cheese"):
            continue

        # 5. Arnold is the person who is a pizza lover.
        if get_house(assignment, "Name", "Arnold") != get_house(assignment, "Lunch", "pizza"):
            continue

        # If all constraints pass, build the solution output
        header = ["House"] + cats
        rows = []
        for h in houses:
            row = [str(h)] + [assignment[cat][h - 1] for cat in cats]
            rows.append(row)

        result = {
            "solution": {
                "header": header,
                "rows": rows
            }
        }
        print(json.dumps(result, ensure_ascii=False))
        return

    # If no solution found (should not happen for a well-posed puzzle)
    print(json.dumps({"solution": {"header": [], "rows": []}}))

if __name__ == "__main__":
    solve()
